import React from "react";
function Home(){
    return(
<div className="flex flex-col items-center bg-[url('https://storage.googleapis.com/tagjs-prod.appspot.com/v1/9w1KRIs84F/wmxh7e84_expires_30_days.png')] bg-cover bg-center pt-[17px] pb-[687px] mb-[110px]">
	<div className="flex justify-between self-stretch mb-[30px] mx-[230px]">
	</div>
	<span className="text-[#2F327D] text-5xl font-bold mb-[1px] ml-[745px] text-center" >
		{"SHIKSHA 2.0"}
	</span>
	<span className="text-white text-2xl font-bold ml-[626px] text-center" >
		{"“ The Gen 2 Spoken English Teaching Robot ”"}
	</span>
</div>
    );
}
export default Home;
